const expected = String($env.TELEGRAM_WEBHOOK_SECRET || '').trim();
const got = String($json.headers?.['x-telegram-bot-api-secret-token'] || $json.headers?.['X-Telegram-Bot-Api-Secret-Token'] || '').trim();

const rawText = String($json.body?.message?.text || $json.body?.edited_message?.text || $json.body?.callback_query?.data || '').trim();
const chatId = String($json.body?.message?.chat?.id ?? $json.body?.edited_message?.chat?.id ?? $json.body?.callback_query?.message?.chat?.id ?? '').trim();

return [{
  ...$json,
  secret_valid: expected ? (got && got === expected) : true,
  has_text: Boolean(rawText),
  chat_id: chatId,
  raw_text: rawText,
}];

const compact = (s) => String(s || '').replace(/\s+/g, ' ').trim();
const text = compact($json.raw_text || '');
const senderUsername = String($json.body?.message?.from?.username || $json.body?.edited_message?.from?.username || $json.body?.callback_query?.from?.username || '').trim();
const sender = senderUsername ? `@${senderUsername}` : String($json.body?.message?.from?.id ?? $json.body?.edited_message?.from?.id ?? $json.body?.callback_query?.from?.id ?? '').trim();
const urlMatch = text.match(/https?:\/\/[^\s]+/i);
const sourceUrl = urlMatch ? urlMatch[0] : null;
const category = /(ai|llm|gpt|gemini|anthropic|prompt)/i.test(text) ? 'ai-ml' : (/(api|sdk|typescript|javascript|python|docker|dev)/i.test(text) ? 'dev-tools' : (/(seo|ads|marketing|growth|lead)/i.test(text) ? 'marketing' : 'general'));
const tags = Array.from(new Set([category, 'telegram', 'knowledge', 'autoro']));
const title = compact(text.split('\n')[0] || text).slice(0, 180) || 'Telegram message';
const aiSummary = text.length > 280 ? `${text.slice(0, 277)}...` : text;
const eventId = `tg-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
const nowIso = new Date().toISOString();

const knowledgeCapturePayload = {
  workspaceId: String($env.KNOWLEDGE_WORKSPACE_ID || '1'),
  source: 'telegram',
  originalSender: sender || null,
  url: sourceUrl,
  title,
  text,
  aiSummary,
  category,
  tags,
  status: 'to_process',
  capturedAt: nowIso,
};

const staticData = $getWorkflowStaticData('global');
if (!staticData.reliableSync) staticData.reliableSync = { pending: {}, failedCapture: [], failedObsidian: [] };
staticData.reliableSync.pending[eventId] = {
  eventId,
  createdAt: nowIso,
  chatId: String($json.chat_id || ''),
  payload: knowledgeCapturePayload,
};

const fallbackMarkdown = [
  '---',
  'source: "Telegram"',
  `original_sender: "${sender || 'unknown'}"`,
  `url: "${sourceUrl || ''}"`,
  `tags: [${tags.join(', ')}]`,
  `date: ${nowIso.slice(0, 10)}`,
  'status: "to_process"',
  `category: "${category}"`,
  `captured_at: "${nowIso}"`,
  '---',
  '',
  `# ${title}`,
  '',
  '### Краткий контекст (AI Generated)',
  aiSummary || text,
  '',
  '### Оригинальное сообщение',
  text,
].join('\n');

return [{
  ...$json,
  event_id: eventId,
  knowledge_capture_payload: knowledgeCapturePayload,
  fallback_markdown: fallbackMarkdown,
}];

const eventId = String($json.event_id || '');
const payload = $json.knowledge_capture_payload || null;
const wsForPath = String((payload && payload.workspaceId) || $env.KNOWLEDGE_WORKSPACE_ID || '1').trim();
const vaultRootFb = String($env.KNOWLEDGE_OBSIDIAN_VAULT_ROOT || '').trim().replace(/\/+$/, '') || ('Autoro KB/ws-' + wsForPath);

const apiBase = String($env.KNOWLEDGE_API_BASE || 'https://swoop.autoro.tech').replace(/\/$/, '');
const apiToken = String($env.KNOWLEDGE_API_TOKEN || '').trim();
const obsidianBase = String($env.OBSIDIAN_LOCAL_REST_URL || 'http://127.0.0.1:27124').replace(/\/$/, '');
const obsidianToken = String($env.OBSIDIAN_LOCAL_REST_API_KEY || '').trim();
const REQ_TIMEOUT_MS = Math.min(15000, Math.max(3000, Number($env.KNOWLEDGE_HTTP_TIMEOUT_MS || 8000) || 8000));

const staticData = $getWorkflowStaticData('global');
if (!staticData.reliableSync) staticData.reliableSync = { pending: {}, failedCapture: [], failedObsidian: [] };

async function postJson(url, headers, body) {
  return this.helpers.httpRequest({
    method: 'POST',
    url,
    headers,
    body,
    json: true,
    returnFullResponse: true,
    timeout: REQ_TIMEOUT_MS,
  });
}

let captureOk = false;
let captureResponseBody = null;
let captureError = null;

if (!payload || !apiToken) {
  captureError = 'Knowledge payload or KNOWLEDGE_API_TOKEN missing';
} else {
  try {
    const r = await postJson.call(this, `${apiBase}/api/v1/knowledge/capture`, {
      Authorization: `Bearer ${apiToken}`,
      'Content-Type': 'application/json',
    }, payload);
    captureOk = (r.statusCode >= 200 && r.statusCode < 300);
    captureResponseBody = r.body;
    if (!captureOk) captureError = `knowledge capture HTTP ${r.statusCode}`;
  } catch (e) {
    captureError = String(e?.message || e || 'capture failed');
  }
}

const notePath = String(captureResponseBody?.obsidian?.notePathSuggested || `${vaultRootFb}/Knowledge Inbox/${new Date().toISOString().slice(0, 10)}/${eventId || 'telegram'}.md`);
const markdown = String(captureResponseBody?.obsidian?.markdown || $json.fallback_markdown || '');

let obsidianOk = false;
let obsidianError = null;

if (!obsidianToken) {
  obsidianError = 'OBSIDIAN_LOCAL_REST_API_KEY missing';
} else {
  try {
    const encodedPath = notePath.split('/').map(encodeURIComponent).join('/');
    const r = await this.helpers.httpRequest({
      method: 'POST',
      url: `${obsidianBase}/vault/${encodedPath}`,
      headers: {
        Authorization: `Bearer ${obsidianToken}`,
        'Content-Type': 'text/markdown; charset=utf-8',
      },
      body: markdown,
      returnFullResponse: true,
      timeout: REQ_TIMEOUT_MS,
    });
    obsidianOk = (r.statusCode >= 200 && r.statusCode < 300);
    if (!obsidianOk) obsidianError = `obsidian write HTTP ${r.statusCode}`;
  } catch (e) {
    obsidianError = String(e?.message || e || 'obsidian failed');
  }
}

if (!captureOk) {
  staticData.reliableSync.failedCapture.push({
    eventId,
    at: new Date().toISOString(),
    error: captureError,
    payload,
  });
}

if (!obsidianOk) {
  staticData.reliableSync.failedObsidian.push({
    eventId,
    at: new Date().toISOString(),
    error: obsidianError,
    notePath,
    markdown,
  });
}

if (captureOk || obsidianOk) {
  delete staticData.reliableSync.pending[eventId];
}

const MAX_QUEUE = 2000;
if (staticData.reliableSync.failedCapture.length > MAX_QUEUE) {
  staticData.reliableSync.failedCapture = staticData.reliableSync.failedCapture.slice(-MAX_QUEUE);
}
if (staticData.reliableSync.failedObsidian.length > MAX_QUEUE) {
  staticData.reliableSync.failedObsidian = staticData.reliableSync.failedObsidian.slice(-MAX_QUEUE);
}

return [{
  ...$json,
  sync_result: {
    eventId,
    captureOk,
    obsidianOk,
    captureError,
    obsidianError,
    notePath,
    knowledgeItemId: captureResponseBody?.knowledgeItemId || null,
    pendingCount: Object.keys(staticData.reliableSync.pending || {}).length,
    failedCaptureCount: (staticData.reliableSync.failedCapture || []).length,
    failedObsidianCount: (staticData.reliableSync.failedObsidian || []).length,
  },
}];

const apiBase = String($env.KNOWLEDGE_API_BASE || 'https://swoop.autoro.tech').replace(/\/$/, '');
const apiToken = String($env.KNOWLEDGE_API_TOKEN || '').trim();
const obsidianBase = String($env.OBSIDIAN_LOCAL_REST_URL || 'http://127.0.0.1:27124').replace(/\/$/, '');
const obsidianToken = String($env.OBSIDIAN_LOCAL_REST_API_KEY || '').trim();

const BATCH_CAPTURE = Math.min(50, Number($env.KNOWLEDGE_RETRY_BATCH_CAPTURE || 25) || 25);
const BATCH_OBSIDIAN = Math.min(50, Number($env.KNOWLEDGE_RETRY_BATCH_OBSIDIAN || 25) || 25);
const REQ_TIMEOUT_MS = Math.min(15000, Math.max(3000, Number($env.KNOWLEDGE_HTTP_TIMEOUT_MS || 8000) || 8000));

const staticData = $getWorkflowStaticData('global');
if (!staticData.reliableSync) staticData.reliableSync = { pending: {}, failedCapture: [], failedObsidian: [] };

const currentFailedCapture = Array.isArray(staticData.reliableSync.failedCapture) ? staticData.reliableSync.failedCapture : [];
const currentFailedObsidian = Array.isArray(staticData.reliableSync.failedObsidian) ? staticData.reliableSync.failedObsidian : [];

const capQueue = [...currentFailedCapture];
const obsQueue = [...currentFailedObsidian];
const capBatch = capQueue.splice(0, BATCH_CAPTURE);
const obsBatch = obsQueue.splice(0, BATCH_OBSIDIAN);

async function tryCapture(entry) {
  if (!apiToken || !entry?.payload) {
    return { ok: false, error: 'missing token or payload' };
  }
  try {
    const r = await this.helpers.httpRequest({
      method: 'POST',
      url: `${apiBase}/api/v1/knowledge/capture`,
      headers: { Authorization: `Bearer ${apiToken}`, 'Content-Type': 'application/json' },
      body: entry.payload,
      json: true,
      returnFullResponse: true,
      timeout: REQ_TIMEOUT_MS,
    });
    const ok = r.statusCode >= 200 && r.statusCode < 300;
    return { ok, error: ok ? null : `HTTP ${r.statusCode}` };
  } catch (e) {
    return { ok: false, error: String(e?.message || e || 'capture retry failed') };
  }
}

async function tryObsidian(entry) {
  if (!obsidianToken || !entry?.notePath || !entry?.markdown) {
    return { ok: false, error: 'missing obsidian token/path/markdown' };
  }
  try {
    const encodedPath = String(entry.notePath).split('/').map(encodeURIComponent).join('/');
    const r = await this.helpers.httpRequest({
      method: 'POST',
      url: `${obsidianBase}/vault/${encodedPath}`,
      headers: { Authorization: `Bearer ${obsidianToken}`, 'Content-Type': 'text/markdown; charset=utf-8' },
      body: String(entry.markdown),
      returnFullResponse: true,
      timeout: REQ_TIMEOUT_MS,
    });
    const ok = r.statusCode >= 200 && r.statusCode < 300;
    return { ok, error: ok ? null : `HTTP ${r.statusCode}` };
  } catch (e) {
    return { ok: false, error: String(e?.message || e || 'obsidian retry failed') };
  }
}

const captureRemaining = [];
const obsidianRemaining = [];
let captureRecovered = 0;
let obsidianRecovered = 0;

for (const entry of capBatch) {
  const res = await tryCapture.call(this, entry);
  if (res.ok) {
    captureRecovered += 1;
  } else {
    captureRemaining.push({ ...entry, lastRetryAt: new Date().toISOString(), error: res.error || entry.error || 'retry failed' });
  }
}

for (const entry of obsBatch) {
  const res = await tryObsidian.call(this, entry);
  if (res.ok) {
    obsidianRecovered += 1;
  } else {
    obsidianRemaining.push({ ...entry, lastRetryAt: new Date().toISOString(), error: res.error || entry.error || 'retry failed' });
  }
}

staticData.reliableSync.failedCapture = [...captureRemaining, ...capQueue];
staticData.reliableSync.failedObsidian = [...obsidianRemaining, ...obsQueue];

return [{
  retry_summary: {
    captureRecovered,
    obsidianRecovered,
    failedCaptureRemaining: staticData.reliableSync.failedCapture.length,
    failedObsidianRemaining: staticData.reliableSync.failedObsidian.length,
    deferredCapture: capQueue.length,
    deferredObsidian: obsQueue.length,
    batchCapture: capBatch.length,
    batchObsidian: obsBatch.length,
    pendingCount: Object.keys(staticData.reliableSync.pending || {}).length,
  },
}];
